INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20M8JUB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$86$ is on sale for $\\$64.50$. What is the percent decrease in price?', NULL, $lyceon_json$[{"key":"A","text":"$21.5\\%$"},{"key":"B","text":"$25\\%$"},{"key":"C","text":"$33.3\\%$"},{"key":"D","text":"$75\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The decrease is $86 - 64.50 = 21.50$. The percent decrease is $\\frac{21.50}{86} \\times 100 = 25\\%$. The answer $21.5\\%$ confuses the dollar amount of decrease with the percentage. The answer $33.3\\%$ results from dividing the decrease by the sale price ($\\frac{21.50}{64.50} \\approx 0.333$) instead of by the original price. The answer $75\\%$ comes from computing $\\frac{64.50}{86} \\times 100$, which gives the fraction of the original price that remains, not the percent decrease.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20Y5Z6G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values 14, 17, 19, 19, 23, 28, and 31. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"17"},{"key":"B","text":"19"},{"key":"C","text":"21.57"},{"key":"D","text":"23"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set has 7 values listed in order. The median is the 4th value, which is 19. The answer 17 results from choosing the 3rd value instead of the 4th, miscounting the middle position. The answer 21.57 is the mean ($\\frac{151}{7} \\approx 21.57$), confusing mean with median. The answer 23 results from selecting the 5th value instead of the 4th, again miscounting the middle position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"graph_read_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22TRXRB', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{4x^2 + 20x + 21}{2x + 3}$ for $x \\neq -\\frac{3}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x - 7$"},{"key":"B","text":"$2x + 3$"},{"key":"C","text":"$2x + 7$"},{"key":"D","text":"$4x + 7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factoring the numerator: $4x^2 + 20x + 21 = (2x + 3)(2x + 7)$. Verification: $(2x + 3)(2x + 7) = 4x^2 + 14x + 6x + 21 = 4x^2 + 20x + 21$. Dividing by $(2x + 3)$ yields $2x + 7$. The distractor $2x - 7$ comes from a sign error on the constant term during factoring. The distractor $2x + 3$ results from incorrectly selecting the divisor itself as the quotient, reflecting a conceptual gap in polynomial division. The distractor $4x + 7$ results from failing to account for the leading coefficient properly when splitting the middle term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22Z69BY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'Given the system of equations $11x - 3y = 35$ and $2x + 7y = 29$, what is the value of $5x - y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Multiply the first equation by $7$: $77x - 21y = 245$. Multiply the second equation by $3$: $6x + 21y = 87$. Adding these eliminates $y$: $83x = 332$, so $x = 4$. Substituting back into $2x + 7y = 29$ gives $8 + 7y = 29$, so $7y = 21$ and $y = 3$. Therefore $5x - y = 5(4) - 3 = 17$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM249OODI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $p$ satisfies the equation $7p - 13 = 50$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$37$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $13$ to both sides gives $7p = 63$. Dividing both sides by $7$ yields $p = 9$. The distractor $-9$ results from a sign error when dividing $63$ by $7$. The distractor $37$ comes from subtracting $13$ from $50$ rather than adding, then failing to divide by $7$. The distractor $63$ comes from stopping after computing $7p = 63$ without completing the final division step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24Y2YQV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $18$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$9\\pi$"},{"key":"B","text":"$18\\pi$"},{"key":"C","text":"$81\\pi$"},{"key":"D","text":"$324\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Substituting $d = 18$ gives $C = 18\\pi$. The value $9\\pi$ results from using the radius ($\\frac{18}{2} = 9$) without the factor of $2$ in the formula $C = 2\\pi r$. The value $81\\pi$ comes from computing $\\pi r^2 = \\pi(9)^2 = 81\\pi$, which is the area rather than the circumference. The value $324\\pi$ results from computing $\\pi d^2 = \\pi(18)^2 = 324\\pi$, squaring the diameter instead of multiplying by $\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24YMVS1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 residents in a county found that 85 of them support a new recycling program. The margin of error for the survey is 6 percentage points. Which of the following is the best estimate of the range of the percentage of all county residents who support the program?', NULL, $lyceon_json$[{"key":"A","text":"28% to 40%"},{"key":"B","text":"34% to 40%"},{"key":"C","text":"30% to 38%"},{"key":"D","text":"22% to 46%"}]$lyceon_json$::jsonb, 'A', NULL, E'The sample proportion is $\\frac{85}{250} = 0.34$, or 34%. With a margin of error of 6 percentage points, the plausible range is $34\\% - 6\\% = 28\\%$ to $34\\% + 6\\% = 40\\%$. The range 34% to 40% only adds the margin of error above the estimate, omitting the lower bound. The range 30% to 38% uses a margin of error of 4 percentage points instead of 6. The range 22% to 46% doubles the margin of error on each side, applying 12 percentage points instead of 6.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26A3DRY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two polling organizations each independently surveyed random samples from the same population of registered voters to estimate support for a ballot measure. Organization X surveyed 400 voters and found 53% support with a margin of error of 5 percentage points. Organization Y surveyed 1,600 voters and found 48% support with a margin of error of 2.5 percentage points. Which of the following statements is best supported by the data?', NULL, $lyceon_json$[{"key":"A","text":"The true level of support is closer to 53% because Organization X found a higher percentage."},{"key":"B","text":"The confidence intervals from the two surveys overlap, so the results are consistent with each other."},{"key":"C","text":"Organization X's result is more reliable because its sample found a higher percentage of support."},{"key":"D","text":"The true level of support must be exactly 50.5% because that is the midpoint of the two estimates."}]$lyceon_json$::jsonb, 'B', NULL, E'Organization X''s interval is 48% to 58%, and Organization Y''s interval is 45.5% to 50.5%. These intervals overlap in the range 48% to 50.5%, so the two results are consistent with each other. The claim that the true level is closer to 53% because one survey found a higher percentage confuses a sample statistic with the population parameter. The claim that a higher sample percentage makes a survey more reliable confuses magnitude of a statistic with precision, which depends on sample size. Averaging the two point estimates to get exactly 50.5% and claiming the true value must equal that average is not supported, because neither survey pinpoints the parameter to an exact value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26IV90O', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'At a fitness center, 310 members were surveyed about their preferred workout type and membership tier. Of the 310 members, 95 prefer weightlifting, 127 prefer cardio, and 88 prefer group classes. Among those who prefer weightlifting, 38 have a premium membership. Among those who prefer cardio, 71 have a premium membership. Among those who prefer group classes, 52 have a premium membership. Given that a randomly selected member has a premium membership, what is the probability that the member prefers group classes?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{52}{88}$"},{"key":"B","text":"$\\frac{52}{161}$"},{"key":"C","text":"$\\frac{88}{310}$"},{"key":"D","text":"$\\frac{52}{310}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of premium members is $38 + 71 + 52 = 161$. Among those 161 premium members, 52 prefer group classes. The conditional probability is $\\frac{52}{161}$. The value $\\frac{52}{88}$ divides by the total who prefer group classes, computing the probability of premium given group classes rather than the requested conditional probability. The value $\\frac{88}{310}$ gives the unconditional probability of preferring group classes, ignoring the premium condition. The value $\\frac{52}{310}$ divides by the total number of members rather than conditioning on premium membership.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26YI0GR', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = ax + b$, where $a$ and $b$ are constants. If $f(3) = 23$ and $f(8) = -7$, what is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$41$"},{"key":"B","text":"$-41$"},{"key":"C","text":"$5$"},{"key":"D","text":"$35$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $a = \\frac{-7 - 23}{8 - 3} = \\frac{-30}{5} = -6$. Using $f(3) = 23$: $-6(3) + b = 23$, so $-18 + b = 23$ and $b = 41$. The distractor $-41$ results from a sign error on the final value. The distractor $5$ comes from subtracting $18$ from $23$ instead of adding, computing $23 - 18 = 5$. The distractor $35$ results from an arithmetic slip, using $x = 2$ instead of $x = 3$ in the substitution step, giving $-12 + b = 23$ and $b = 35$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM278JOV3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A set of 20 data points is modeled by the equation $y = -0.43x + 57.1$. One data point has coordinates $(30, 47.2)$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$3.0$"},{"key":"B","text":"$-3.0$"},{"key":"C","text":"$9.9$"},{"key":"D","text":"$-9.9$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value at $x = 30$ is $y = -0.43(30) + 57.1 = -12.9 + 57.1 = 44.2$. The residual is the observed value minus the predicted value: $47.2 - 44.2 = 3.0$. The answer $-3.0$ reverses the residual formula by computing predicted minus observed. The answer $9.9$ results from an error in computing the predicted value, such as using $-0.43(30) + 57.1 = 37.3$ and then finding $47.2 - 37.3 = 9.9$. The answer $-9.9$ combines an incorrect predicted value with the reversed subtraction order.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27BF7OP', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $\\ell$ passes through the points $(2, -3)$ and $(5, 9)$. What is the $y$-intercept of line $\\ell$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-11', ARRAY['-11'], E'The slope of the line is $m = \\frac{9 - (-3)}{5 - 2} = \\frac{12}{3} = 4$. Using point-slope form with the point $(2, -3)$: $y - (-3) = 4(x - 2)$, which gives $y + 3 = 4x - 8$, so $y = 4x - 11$. The $y$-intercept is $-11$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27QEG3U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher studies whether students who eat breakfast daily have higher exam scores than those who skip breakfast. She collects data from 430 students by surveying their breakfast habits and recording their final exam scores. She finds that students who eat breakfast daily score an average of 7 points higher. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast daily causes higher exam scores."},{"key":"B","text":"There is an association between eating breakfast daily and higher exam scores, but a causal relationship cannot be established."},{"key":"C","text":"Students who skip breakfast should begin eating breakfast to raise their exam scores."},{"key":"D","text":"The difference in scores is due to random chance because the sample size is too small."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researcher did not randomly assign students to eat or skip breakfast, this is an observational study. Observational studies can identify associations but cannot establish causation, since confounding variables (such as sleep habits, motivation, or socioeconomic factors) may explain the difference. The claim that breakfast causes higher scores goes beyond what an observational study supports. The recommendation to change behavior assumes a causal link that has not been established. The claim that the result is random chance due to small sample size is unsupported, as 430 students is a reasonably large sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM288QJ3O', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A fitness center charges a one-time registration fee plus a fixed monthly rate. After $3$ months of membership, the total amount paid is $\\$207$. After $7$ months of membership, the total amount paid is $\\$367$. What is the monthly rate, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'Let $m$ be the monthly rate and $e$ be the registration fee. Then $e + 3m = 207$ and $e + 7m = 367$. Subtracting the first equation from the second eliminates $e$: $4m = 160$, so $m = 40$. The monthly rate is $\\$40$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28M3ON4', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{2x^3 + 7x^2 - 17x + 3}{2x + 1}$ can be written in the form $x^2 + bx + c + \\frac{r}{2x + 1}$, where $b$, $c$, and $r$ are constants. What is the value of $b + c + r$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Performing polynomial long division of $2x^3 + 7x^2 - 17x + 3$ by $2x + 1$: first, $2x^3 \\div 2x = x^2$. Multiplying $x^2(2x + 1) = 2x^3 + x^2$ and subtracting from the dividend gives $6x^2 - 17x + 3$. Next, $6x^2 \\div 2x = 3x$, so $b = 3$. Multiplying $3x(2x + 1) = 6x^2 + 3x$ and subtracting gives $-20x + 3$. Then $-20x \\div 2x = -10$, so $c = -10$. Multiplying $-10(2x + 1) = -20x - 10$ and subtracting gives the remainder $r = 13$. Therefore $b + c + r = 3 + (-10) + 13 = 6$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28YW3GN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one of the acute angles has measure $\\theta$. If $\\sin(\\theta) = \\frac{11}{61}$, what is the value of $\\cos(\\theta)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{60}$"},{"key":"B","text":"$\\frac{50}{61}$"},{"key":"C","text":"$\\frac{60}{61}$"},{"key":"D","text":"$\\frac{60}{11}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin(\\theta) = \\frac{11}{61}$, the side opposite $\\theta$ is $11$ and the hypotenuse is $61$. Using the Pythagorean theorem, the adjacent side is $\\sqrt{61^2 - 11^2} = \\sqrt{3721 - 121} = \\sqrt{3600} = 60$. Therefore $\\cos(\\theta) = \\frac{60}{61}$. The value $\\frac{11}{60}$ confuses cosine with tangent ($\\frac{\\text{opposite}}{\\text{adjacent}}$). The value $\\frac{50}{61}$ results from subtracting $11$ from $61$ instead of using the Pythagorean theorem correctly. The value $\\frac{60}{11}$ is $\\cot(\\theta)$, which uses the wrong denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM297I0D0', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 2x - 35 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 7$ and $x = -5$"},{"key":"B","text":"$x = -7$ and $x = 5$"},{"key":"C","text":"$x = 7$ and $x = 5$"},{"key":"D","text":"$x = -7$ and $x = -5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring the quadratic: $x^2 - 2x - 35 = (x - 7)(x + 5) = 0$. Verification: $(x - 7)(x + 5) = x^2 + 5x - 7x - 35 = x^2 - 2x - 35$. Setting each factor to zero gives $x = 7$ or $x = -5$. The distractor $x = -7$ and $x = 5$ reverses the signs of both solutions. The distractor $x = 7$ and $x = 5$ changes the sign of only the negative root. The distractor $x = -7$ and $x = -5$ takes both factor constants as negative without correctly solving each linear equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2993QBB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangle has a base of $22$ inches and a height of $9$ inches. What is the area, in square inches, of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$31$"},{"key":"B","text":"$99$"},{"key":"C","text":"$126$"},{"key":"D","text":"$198$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a triangle is $A = \\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2}(22)(9) = 99$ square inches. The value $31$ results from adding the base and height ($22 + 9$) instead of using the area formula. The value $126$ arises from an arithmetic error in the multiplication step. The value $198$ comes from computing $22 \\times 9 = 198$ without dividing by $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29D6790', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $8x - 13 > 27$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding $13$ to both sides gives $8x > 40$, and dividing both sides by $8$ gives $x > 5$. The only value greater than $5$ among the choices is $7$. The value $5$ fails because the inequality is strict: $8(5) - 13 = 27$, which is not greater than $27$. The values $3$ and $4$ are both less than $5$ and produce results well below $27$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29XADZF', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 9x - 17$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$44$"},{"key":"C","text":"$10$"},{"key":"D","text":"$-10$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 3$: $f(3) = 9(3) - 17 = 27 - 17 = 10$. The distractor $27$ comes from computing $9 \\times 3$ but neglecting to subtract $17$. The distractor $44$ comes from adding $17$ instead of subtracting, giving $27 + 17 = 44$. The distractor $-10$ results from a sign error on the final result.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A98QLI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $20$ and $21$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$29$"},{"key":"C","text":"$41$"},{"key":"D","text":"$841$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem, $c = \\sqrt{20^2 + 21^2} = \\sqrt{400 + 441} = \\sqrt{841} = 29$. The value $1$ results from subtracting the legs ($21 - 20$) instead of applying the theorem. The value $41$ comes from adding the legs ($20 + 21$) rather than using the correct formula. The value $841$ is the square of the hypotenuse ($c^2$), forgetting to take the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AUQ18D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher wants to determine whether a new vitamin supplement reduces the frequency of headaches. She randomly assigns 60 volunteers to take the supplement daily and another 60 volunteers to take a placebo daily for eight weeks. She then compares the average number of headaches per week between the two groups. This study is best described as which of the following?', NULL, $lyceon_json$[{"key":"A","text":"A survey"},{"key":"B","text":"An observational study"},{"key":"C","text":"An experiment"},{"key":"D","text":"A case study"}]$lyceon_json$::jsonb, 'C', NULL, E'Because the researcher randomly assigns participants to a treatment group (supplement) and a control group (placebo), this is an experiment. A survey collects self-reported data without any intervention. An observational study records existing behaviors or outcomes without imposing a treatment. A case study examines one or a few individuals in depth rather than comparing groups.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BCZJXB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer produces 37 pages every 4 minutes. At this constant rate, how many pages does the printer produce in 52 minutes?', NULL, $lyceon_json$[{"key":"A","text":"370"},{"key":"B","text":"481"},{"key":"C","text":"444"},{"key":"D","text":"518"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{37}{4} = 9.25$ pages per minute. In 52 minutes the printer produces $9.25 \\times 52 = 481$ pages. Equivalently, $\\frac{52}{4} = 13$ intervals, so $37 \\times 13 = 481$. The answer 370 results from incorrectly computing $37 \\times 10$, misidentifying the number of intervals. The answer 444 comes from computing $37 \\times 12$ instead of $37 \\times 13$. The answer 518 comes from computing $37 \\times 14$, overstating the number of intervals.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BJJ31I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A researcher finds that the line of best fit for a data set is $y = 2.3x + 11$. According to this model, what is the predicted value of $y$ when $x = 9$?', NULL, $lyceon_json$[{"key":"A","text":"31.7"},{"key":"B","text":"29.3"},{"key":"C","text":"20.7"},{"key":"D","text":"11"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 9$ into the equation: $y = 2.3(9) + 11 = 20.7 + 11 = 31.7$. The answer 29.3 results from an arithmetic slip such as computing $2.3 \\times 9 = 18.3$ instead of 20.7. The answer 20.7 comes from computing only $2.3 \\times 9$ but forgetting to add the $y$-intercept of 11. The answer 11 results from reading only the $y$-intercept and ignoring the slope term entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BJLLRP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 2x^2 + 12x + 7$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$7$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since the leading coefficient is positive, the parabola opens upward and has a minimum at its vertex. The $x$-coordinate of the vertex is $x = \\frac{-12}{2(2)} = -3$. Evaluating: $f(-3) = 2(9) + 12(-3) + 7 = 18 - 36 + 7 = -11$. The minimum value is $-11$. The distractor $-3$ gives the $x$-coordinate of the vertex rather than the minimum value of the function. The distractor $7$ gives the $y$-intercept $f(0) = 7$, confusing it with the minimum. The distractor $11$ results from a sign error that yields the absolute value of the minimum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C0V67Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A data set of 11 values has a mean of 36. A 12th value of 24 is added to the set. What is the mean of the new 12-value data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '35', ARRAY['35'], E'The original sum is $11 \\times 36 = 396$. Adding 24 gives a new sum of $396 + 24 = 420$. The new mean is $\\frac{420}{12} = 35$. Note that any additional information about the median or spread of the original data set is not needed to compute the new mean.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CAECPM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The equations $y = x^2 - 4x + 1$ and $y = 2x - 7$ form a system. What is the sum of the $y$-coordinates of the solutions to this system?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$2$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the expressions equal: $x^2 - 4x + 1 = 2x - 7$, which simplifies to $x^2 - 6x + 8 = 0$. Factoring: $(x - 2)(x - 4) = 0$, so $x = 2$ or $x = 4$. Substituting into $y = 2x - 7$: when $x = 2$, $y = -3$; when $x = 4$, $y = 1$. The sum of the $y$-coordinates is $-3 + 1 = -2$. The distractor $-6$ results from incorrectly summing the $x$-coordinates with a sign error ($-2 + (-4) = -6$). The distractor $2$ comes from a sign error when adding $-3 + 1$ and getting the opposite sign. The distractor $6$ results from summing the $x$-coordinates ($2 + 4 = 6$) instead of the $y$-coordinates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CE68FC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A city''s population was 31,000 at the start of 2020. It increased by $4\\%$ during 2020, decreased by $7\\%$ during 2021, and then increased by $3\\%$ during 2022. What was the population at the end of 2022, rounded to the nearest whole number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30883', ARRAY['30883'], E'After 2020: $31{,}000 \\times 1.04 = 32{,}240$. After 2021: $32{,}240 \\times 0.93 = 29{,}983.2$. After 2022: $29{,}983.2 \\times 1.03 = 30{,}882.696$. Rounded to the nearest whole number, the population is $30{,}883$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CIZ5H3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $7$ centimeters and a height of $11$ centimeters. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$77\\pi$ cubic centimeters"},{"key":"B","text":"$154\\pi$ cubic centimeters"},{"key":"C","text":"$343\\pi$ cubic centimeters"},{"key":"D","text":"$539\\pi$ cubic centimeters"}]$lyceon_json$::jsonb, 'D', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(7)^2(11) = \\pi(49)(11) = 539\\pi$ cubic centimeters. The value $77\\pi$ results from using $\\pi r h$ instead of $\\pi r^2 h$, omitting the squaring of the radius ($7 \\times 11 = 77$). The value $154\\pi$ comes from computing the lateral surface area ($2\\pi r h = 2\\pi(7)(11) = 154\\pi$) instead of the volume. The value $343\\pi$ results from cubing the radius ($7^3 = 343$) instead of squaring it and multiplying by the height.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CVX30V', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $g$ is defined such that $g(5) = 37$ and $g(13) = -19$. For what value of $x$ does $g(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '72/7', ARRAY['72/7', '10.28', '10.29'], E'The slope of $g$ is $\\frac{-19 - 37}{13 - 5} = \\frac{-56}{8} = -7$. Using the point $(5, 37)$: $g(x) = -7(x - 5) + 37 = -7x + 35 + 37 = -7x + 72$. Setting $g(x) = 0$: $-7x + 72 = 0$, so $7x = 72$ and $x = \\frac{72}{7}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ERTVAW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{3}{x - 5} - \\frac{2}{x + 7}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 11}{x^2 + 2x - 35}$"},{"key":"B","text":"$\\frac{x + 31}{x^2 + 2x - 35}$"},{"key":"C","text":"$\\frac{x + 31}{x^2 - 2x - 35}$"},{"key":"D","text":"$\\frac{1}{x^2 + 2x - 35}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The common denominator is $(x - 5)(x + 7) = x^2 + 2x - 35$. Rewriting: $\\frac{3(x + 7) - 2(x - 5)}{x^2 + 2x - 35} = \\frac{3x + 21 - 2x + 10}{x^2 + 2x - 35} = \\frac{x + 31}{x^2 + 2x - 35}$. The distractor $\\frac{x + 11}{x^2 + 2x - 35}$ results from a sign error when distributing the negative: computing $21 - 10 = 11$ instead of $21 + 10 = 31$. The distractor $\\frac{x + 31}{x^2 - 2x - 35}$ has the correct numerator but a sign error in the cross term of the denominator. The distractor $\\frac{1}{x^2 + 2x - 35}$ results from subtracting only the numerators ($3 - 2 = 1$) without finding a common denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GL4WRZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A box contains 13 red tokens and 8 blue tokens. Two tokens are drawn at random without replacement. What is the probability that the first token drawn is red and the second token drawn is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{21} \\cdot \\frac{8}{21}$"},{"key":"B","text":"$\\frac{13}{21} \\cdot \\frac{8}{20}$"},{"key":"C","text":"$\\frac{13}{21} \\cdot \\frac{7}{20}$"},{"key":"D","text":"$\\frac{8}{21} \\cdot \\frac{13}{20}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The probability that the first token is red is $\\frac{13}{21}$. After removing one red token, there are 20 tokens remaining, of which 8 are blue. The probability that the second token is blue is $\\frac{8}{20}$. The combined probability is $\\frac{13}{21} \\cdot \\frac{8}{20}$. The expression $\\frac{13}{21} \\cdot \\frac{8}{21}$ treats the draws as independent (with replacement), failing to reduce the pool after the first draw. The expression $\\frac{13}{21} \\cdot \\frac{7}{20}$ incorrectly reduces the blue count by 1 instead of the red count, as though a blue token was removed first. The expression $\\frac{8}{21} \\cdot \\frac{13}{20}$ reverses the order, computing the probability of blue first and red second rather than the requested sequence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I508BT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'Machine A fills 53 bottles every 6 minutes. Machine B fills 41 bottles every 5 minutes. Both machines start at the same time and run for exactly 30 minutes. What is the total number of bottles filled by both machines combined?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '511', ARRAY['511'], E'Machine A''s rate is $\\frac{53}{6}$ bottles per minute. In 30 minutes, Machine A fills $\\frac{53}{6} \\times 30 = 53 \\times 5 = 265$ bottles. Machine B''s rate is $\\frac{41}{5}$ bottles per minute. In 30 minutes, Machine B fills $\\frac{41}{5} \\times 30 = 41 \\times 6 = 246$ bottles. The total is $265 + 246 = 511$ bottles.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IXLVW1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line is perpendicular to the line $3x - 7y = 14$ and passes through the point $(6, -1)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$-13$"},{"key":"C","text":"$14$"},{"key":"D","text":"$-2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $3x - 7y = 14$ in slope-intercept form gives $y = \\frac{3}{7}x - 2$, so the slope is $\\frac{3}{7}$. The perpendicular slope is $-\\frac{7}{3}$. Using point-slope form with $(6, -1)$: $y + 1 = -\\frac{7}{3}(x - 6)$, which gives $y + 1 = -\\frac{7}{3}x + 14$, so $y = -\\frac{7}{3}x + 13$. The $y$-intercept is $13$. The distractor $-13$ results from a sign error on the final intercept. The distractor $14$ comes from stopping at the intermediate calculation $-\\frac{7}{3}(x - 6)$ and reading $14$ without subtracting $1$. The distractor $-2$ is the $y$-intercept of the original line, not the perpendicular line.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JMSJME', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(2x^2 + 5) - (x^2 - 4)$?', NULL, $lyceon_json$[{"key":"A","text":"$5x^2 + 19$"},{"key":"B","text":"$5x^2 + 11$"},{"key":"C","text":"$7x^2 + 19$"},{"key":"D","text":"$7x^2 + 11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the $3$ gives $6x^2 + 15$. Distributing the subtraction sign across $(x^2 - 4)$ gives $-x^2 + 4$. Combining: $6x^2 - x^2 = 5x^2$ and $15 + 4 = 19$, so the result is $5x^2 + 19$. The distractor $5x^2 + 11$ results from a sign error when distributing the negative: subtracting $4$ instead of adding it ($15 - 4 = 11$). The distractor $7x^2 + 19$ results from a sign error that adds $x^2$ instead of subtracting it ($6x^2 + x^2 = 7x^2$). The distractor $7x^2 + 11$ combines both sign errors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JWN9FI', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $kx + 8y = 11$ and $21x - 12y = -21$ has no solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-14$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$7$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system has no solution when the lines are parallel but not identical, meaning the ratios of the coefficients of $x$ and $y$ are equal but the ratio of the constants differs. Setting $\\frac{k}{21} = \\frac{8}{-12}$ gives $\\frac{k}{21} = -\\frac{2}{3}$, so $k = 21 \\cdot \\left(-\\frac{2}{3}\\right) = -14$. Checking the constant ratio: $\\frac{11}{-21} \\neq -\\frac{2}{3}$, confirming the system is inconsistent and has no solution. Choosing $14$ or $7$ results from dropping the negative sign during the cross-multiplication. Choosing $-7$ comes from incorrectly computing $21 \\cdot \\left(-\\frac{1}{3}\\right)$ by using the wrong ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K9V932', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{5(3w + 2)}{7} - 4 = w + 3$, what is the value of $w$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '39/8', ARRAY['39/8', '4.875'], E'Multiply every term by $7$ to clear the denominator: $5(3w + 2) - 28 = 7w + 21$. Distribute on the left: $15w + 10 - 28 = 7w + 21$, which simplifies to $15w - 18 = 7w + 21$. Subtract $7w$ from both sides: $8w - 18 = 21$. Add $18$ to both sides: $8w = 39$, so $w = \\frac{39}{8}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KMDL6Q', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = \\frac{x^2 - 9x + 14}{x^2 - 11x + 28}$. Which of the following correctly describes the behavior of $y = f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"The graph has vertical asymptotes at $x = 4$ and $x = 7$."},{"key":"B","text":"The graph has a hole at $x = 4$ and a vertical asymptote at $x = 7$."},{"key":"C","text":"The graph has a hole at $x = 7$ and a vertical asymptote at $x = 4$."},{"key":"D","text":"The graph has no vertical asymptote and a hole at $x = 7$."}]$lyceon_json$::jsonb, 'C', NULL, E'Factoring the numerator: $x^2 - 9x + 14 = (x - 2)(x - 7)$. Factoring the denominator: $x^2 - 11x + 28 = (x - 4)(x - 7)$. The common factor $(x - 7)$ cancels, leaving $f(x) = \\frac{x - 2}{x - 4}$ for $x \\neq 7$. Because $(x - 7)$ cancels, the function has a removable discontinuity (hole) at $x = 7$. The remaining factor $(x - 4)$ in the denominator creates a vertical asymptote at $x = 4$. The description stating vertical asymptotes at both $x = 4$ and $x = 7$ fails to recognize that the shared factor produces a hole, not an asymptote. The description placing the hole at $x = 4$ and the asymptote at $x = 7$ reverses which factor cancels. The description claiming no vertical asymptote overlooks the non-canceling factor $(x - 4)$ in the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LKUUZ6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle in the $xy$-plane has equation $x^2 + y^2 + 14x - 4y - 11 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'To find the radius, complete the square for both variables. Group terms: $(x^2 + 14x) + (y^2 - 4y) = 11$. Complete the square for $x$: $x^2 + 14x + 49 = (x + 7)^2$, adding $49$ to both sides. Complete the square for $y$: $y^2 - 4y + 4 = (y - 2)^2$, adding $4$ to both sides. The equation becomes $(x + 7)^2 + (y - 2)^2 = 11 + 49 + 4 = 64$. Since $r^2 = 64$, the radius is $r = 8$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M0Y3N4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'Which ordered pair $(x, y)$ satisfies the equation $5x - 4y = 31$?', NULL, $lyceon_json$[{"key":"A","text":"$(3, 4)$"},{"key":"B","text":"$(7, 1)$"},{"key":"C","text":"$(9, 2)$"},{"key":"D","text":"$(4, 3)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $(7, 1)$: $5(7) - 4(1) = 35 - 4 = 31$, which satisfies the equation. Substituting $(3, 4)$: $5(3) - 4(4) = 15 - 16 = -1 \\neq 31$, an arithmetic slip from choosing values that do not satisfy the equation. Substituting $(9, 2)$: $5(9) - 4(2) = 45 - 8 = 37 \\neq 31$, from an equation setup error that produces a value close to but not equal to $31$. Substituting $(4, 3)$: $5(4) - 4(3) = 20 - 12 = 8 \\neq 31$, a sign-related error from swapping the roles of $x$ and $y$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MBBY3F', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has center $(-5, 7)$ and passes through the point $(-5, 18)$. Which of the following is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 5)^2 + (y + 7)^2 = 121$"},{"key":"B","text":"$(x + 5)^2 + (y - 7)^2 = 11$"},{"key":"C","text":"$(x + 5)^2 + (y - 7)^2 = 121$"},{"key":"D","text":"$(x - 5)^2 + (y - 7)^2 = 121$"}]$lyceon_json$::jsonb, 'C', NULL, E'The radius is the distance from $(-5, 7)$ to $(-5, 18)$: $r = |18 - 7| = 11$. The standard form of a circle with center $(h, k)$ is $(x - h)^2 + (y - k)^2 = r^2$. Substituting gives $(x - (-5))^2 + (y - 7)^2 = 11^2$, which simplifies to $(x + 5)^2 + (y - 7)^2 = 121$. The option $(x - 5)^2 + (y + 7)^2 = 121$ reverses both signs in the center coordinates. The option $(x + 5)^2 + (y - 7)^2 = 11$ uses the radius instead of the radius squared. The option $(x - 5)^2 + (y - 7)^2 = 121$ incorrectly uses $(x - 5)$ instead of $(x + 5)$ for the $x$-coordinate of the center.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O2RJBZ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A print shop charges a \\$17 setup fee plus \\$6 per poster. A customer has a budget of no more than \\$89. What is the maximum number of posters the customer can order?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$11$"},{"key":"C","text":"$12$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total cost for $n$ posters is $17 + 6n$. Setting up the inequality $17 + 6n \\leq 89$ and subtracting $17$ from both sides gives $6n \\leq 72$, so $n \\leq 12$. The maximum whole number of posters is $12$. Choosing $13$ results from an error in setting up the inequality, such as omitting the setup fee. Choosing $11$ comes from rounding down unnecessarily when $12$ already satisfies the inequality exactly. Choosing $10$ results from a subtraction slip such as computing $89 - 17 = 66$ instead of $72$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PSDGJ8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The test scores for 9 students are: 61, 67, 72, 74, 74, 79, 83, 88, and 91. If the score of 91 is replaced by 143, which of the following measures changes?', NULL, $lyceon_json$[{"key":"A","text":"Median only"},{"key":"B","text":"Mean only"},{"key":"C","text":"Both mean and median"},{"key":"D","text":"Neither mean nor median"}]$lyceon_json$::jsonb, 'B', NULL, E'The median of 9 values is the 5th value when ordered. In both the original and modified data sets, the 5th value is 74, so the median does not change. The mean changes because the sum increases by $143 - 91 = 52$, raising the mean from $\\frac{689}{9} \\approx 76.56$ to $\\frac{741}{9} \\approx 82.33$. Therefore only the mean changes. Choosing median only incorrectly assumes the outlier shifts the middle value. Choosing both incorrectly assumes changing any value always affects the median. Choosing neither incorrectly assumes an extreme value does not affect the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PUS5IA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 11 blue marbles, 6 orange marbles, and 9 white marbles. If one marble is selected at random, what is the probability that the marble is orange?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{6}{26}$"},{"key":"B","text":"$\\frac{6}{20}$"},{"key":"C","text":"$\\frac{11}{26}$"},{"key":"D","text":"$\\frac{9}{26}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $11 + 6 + 9 = 26$. The probability of selecting an orange marble is $\\frac{6}{26}$. The value $\\frac{6}{20}$ divides by only the non-orange total, misapplying the definition of probability. The value $\\frac{11}{26}$ uses the count of blue marbles instead of orange. The value $\\frac{9}{26}$ uses the count of white marbles instead of orange.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q0OH2E', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A chemist has two solutions. Solution A contains $11$ grams of salt per liter, and Solution B contains $3$ grams of salt per liter. She mixes some amount of Solution A with $14$ liters of Solution B to create a mixture that contains $6$ grams of salt per liter. How many liters of Solution A does she use?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{42}{5}$"},{"key":"B","text":"$6$"},{"key":"C","text":"$\\frac{14}{3}$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $a$ be the liters of Solution A. The total salt is $11a + 3(14) = 11a + 42$ grams. The total volume is $a + 14$ liters. Setting the concentration equal to $6$: $\\frac{11a + 42}{a + 14} = 6$. Cross-multiplying gives $11a + 42 = 6a + 84$, so $5a = 42$ and $a = \\frac{42}{5}$. The distractor $6$ comes from incorrectly setting up the equation as $11a + 42 = 6 \\cdot 14$, which omits the volume of Solution A from the total. The distractor $\\frac{14}{3}$ results from an incorrect ratio of concentration differences. The distractor $14$ assumes equal volumes of both solutions are needed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q49GKB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A biologist counts 138 insects in a $\\frac{3}{8}$-acre plot. If insects are uniformly distributed, how many insects would be expected in a 7-acre area?', NULL, $lyceon_json$[{"key":"A","text":"2,576"},{"key":"B","text":"2,208"},{"key":"C","text":"966"},{"key":"D","text":"3,864"}]$lyceon_json$::jsonb, 'A', NULL, E'The density is $\\frac{138}{3/8} = 138 \\times \\frac{8}{3} = 368$ insects per acre. In 7 acres the expected count is $368 \\times 7 = 2{,}576$. The answer 2,208 results from an arithmetic slip such as computing $368 \\times 6$ instead of $368 \\times 7$. The answer 966 comes from computing $138 \\times 7 = 966$, failing to account for the fractional acre size of the sample plot. The answer 3,864 results from computing $138 \\times 8 \\times 3.5$, misapplying the fractional acre factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q509YG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Triangle $RST$ is similar to triangle $UVW$. In triangle $RST$, $RS = 9$, $ST = 14$, and $RT = 19$. If the shortest side of triangle $UVW$ has length $27$, what is the length of the longest side of triangle $UVW$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '57', ARRAY['57'], E'Since the triangles are similar, corresponding sides are proportional. The shortest side of triangle $RST$ is $RS = 9$, and the shortest side of triangle $UVW$ is $27$, so the scale factor is $\\frac{27}{9} = 3$. The longest side of triangle $RST$ is $RT = 19$. Multiplying by the scale factor gives the longest side of triangle $UVW$ as $19 \\times 3 = 57$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QMWYYT', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'At a school fundraiser, adult tickets cost \\$7 each and child tickets cost \\$3 each. A total of $53$ tickets were sold for \\$251. How many child tickets were sold?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30', ARRAY['30'], E'Let $a$ represent the number of adult tickets and $c$ represent the number of child tickets. The system of equations is $a + c = 53$ and $7a + 3c = 251$. From the first equation, $a = 53 - c$. Substituting into the second equation: $7(53 - c) + 3c = 251$, which simplifies to $371 - 7c + 3c = 251$, so $-4c = -120$ and $c = 30$. Verification: $a = 23$, and $7(23) + 3(30) = 161 + 90 = 251$, confirming the total revenue.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RFXI21', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A wildlife ecologist captures and tags 85 deer in a forest preserve. Three weeks later, she captures a second random sample of 68 deer and finds that 17 of them are tagged. Based on this capture-recapture method, which of the following is the best estimate of the total number of deer in the preserve?', NULL, $lyceon_json$[{"key":"A","text":"170"},{"key":"B","text":"240"},{"key":"C","text":"340"},{"key":"D","text":"510"}]$lyceon_json$::jsonb, 'C', NULL, E'Using the capture-recapture proportion: $\\frac{17}{68} = \\frac{85}{N}$. Solving gives $N = \\frac{85 \\times 68}{17} = 340$. The value 170 results from computing $85 \\times 68 / 34$, using an incorrect divisor. The value 240 comes from an arithmetic error such as $85 \\times 68 / 24$. The value 510 results from multiplying $85 \\times 6$ incorrectly, mishandling the ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RSMS0H', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $\\sqrt{3x + 7} = x - 1$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Squaring both sides: $3x + 7 = (x - 1)^2 = x^2 - 2x + 1$. Rearranging: $0 = x^2 - 5x - 6 = (x - 6)(x + 1)$, giving $x = 6$ or $x = -1$. Checking $x = 6$: $\\sqrt{3(6) + 7} = \\sqrt{25} = 5$ and $6 - 1 = 5$, so $x = 6$ is valid. Checking $x = -1$: $\\sqrt{3(-1) + 7} = \\sqrt{4} = 2$ and $-1 - 1 = -2$, so $x = -1$ is extraneous because $2 \\neq -2$. The only solution is $x = 6$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T6PFYG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tests a new sleep medication. They recruit 200 adult volunteers from a single hospital''s insomnia clinic and randomly assign 100 to receive the medication and 100 to receive a placebo for four weeks. At the end of the trial, the medication group reports an average of 1.3 more hours of sleep per night than the placebo group. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The medication causes an increase in sleep duration for all adults with insomnia."},{"key":"B","text":"The medication causes an increase in sleep duration, and this result can be generalized to all adults."},{"key":"C","text":"The medication causes an increase in sleep duration for adults similar to those in the study, but the result cannot be generalized to all adults with insomnia."},{"key":"D","text":"There is an association between the medication and increased sleep duration, but a causal conclusion is not supported."}]$lyceon_json$::jsonb, 'C', NULL, E'Because participants were randomly assigned to treatment and control groups, a causal conclusion is supported. However, the volunteers were recruited from a single hospital''s insomnia clinic rather than randomly selected from the broader population, so the results can only be generalized to adults similar to those in the study. The claim that the result applies to all adults with insomnia overgeneralizes beyond the study''s sampling frame. The claim that it applies to all adults ignores both the non-random selection and the specific population (insomnia patients). The claim that causation is not supported is incorrect because random assignment of the treatment does justify a causal inference within the study population.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TDSBU7', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'How many integers $x$ satisfy both $\\frac{3x - 7}{4} \\geq 2$ and $5 - 2x > -13$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'For the first inequality, multiply both sides by $4$: $3x - 7 \\geq 8$. Adding $7$ gives $3x \\geq 15$, so $x \\geq 5$. For the second inequality, subtract $5$ from both sides: $-2x > -18$. Dividing by $-2$ and flipping the inequality sign yields $x < 9$. Combining the two results: $5 \\leq x < 9$. The integers satisfying this compound inequality are $5, 6, 7, 8$, giving a total of $4$ integers.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TQB3TP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $WXY$, angle $W$ measures $29^\\circ$ and angle $X$ measures $114^\\circ$. What is the measure, in degrees, of angle $Y$?', NULL, $lyceon_json$[{"key":"A","text":"$37^\\circ$"},{"key":"B","text":"$47^\\circ$"},{"key":"C","text":"$57^\\circ$"},{"key":"D","text":"$143^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Therefore, angle $Y = 180^\\circ - 29^\\circ - 114^\\circ = 37^\\circ$. The value $47^\\circ$ results from a subtraction error when computing $180 - 29 - 114$. The value $57^\\circ$ arises from a different arithmetic miscalculation. The value $143^\\circ$ comes from finding the supplement of the correct answer ($180 - 37$) rather than the angle itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U6ZLVG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A store increases the price of a television by $12\\%$ and then offers a $12\\%$ discount on the new price. If the original price was $\\$1{,}150$, what is the final price after both changes?', NULL, $lyceon_json$[{"key":"A","text":"$\\$1{,}133.44$"},{"key":"B","text":"$\\$1{,}150.00$"},{"key":"C","text":"$\\$1{,}288.00$"},{"key":"D","text":"$\\$1{,}012.00$"}]$lyceon_json$::jsonb, 'A', NULL, E'After a $12\\%$ increase: $1{,}150 \\times 1.12 = 1{,}288$. After a $12\\%$ decrease from the new price: $1{,}288 \\times 0.88 = 1{,}133.44$. The answer $\\$1{,}150.00$ reflects the misconception that an equal percentage increase and decrease cancel out and return to the original price. The answer $\\$1{,}288.00$ results from computing only the increase and ignoring the subsequent discount. The answer $\\$1{,}012.00$ comes from subtracting $12\\%$ of the original price twice ($1{,}150 - 2 \\times 138 = 874$), which is also incorrect, or a similar arithmetic misstep.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V04FJW', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$5x + 2y = 29$$ $$x - 2y = -5$$ What is the value of $x$ in the solution to the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates $y$: $(5x + 2y) + (x - 2y) = 29 + (-5)$, which gives $6x = 24$, so $x = 4$. Choosing $5$ results from solving for $y$ instead, since $y = \\frac{29 - 5(4)}{2} = \\frac{9}{2}$, and rounding or misreading the requested variable. Choosing $6$ comes from a sign error when adding the constant terms, such as computing $29 + 5 = 34$ instead of $29 + (-5) = 24$. Choosing $3$ results from a division slip such as $24 \\div 8$ instead of $24 \\div 6$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VP3MPF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A right circular cone has a volume of $147\\pi$ cubic centimeters and a height of $9$ centimeters. What is the radius, in centimeters, of the base of the cone?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h$. Substituting the given values: $147\\pi = \\frac{1}{3}\\pi r^2(9)$. Simplifying the right side: $\\frac{1}{3}(9) = 3$, so $147\\pi = 3\\pi r^2$. Dividing both sides by $3\\pi$ gives $r^2 = 49$. Taking the square root yields $r = 7$ centimeters.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W7V6SX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 2x^2 - 9x + 3$. What is the value of $g(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$98$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 5$: $g(5) = 2(25) - 9(5) + 3 = 50 - 45 + 3 = 8$. The distractor $-2$ results from a sign error when combining terms, such as computing $-50 + 45 + 3$. The distractor $5$ comes from computing $50 - 45$ but omitting the constant term $+3$, reflecting partial reasoning. The distractor $98$ results from an arithmetic slip that adds all terms instead of subtracting: $50 + 45 + 3 = 98$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XBUVOW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $ABC$ with the right angle at $C$, $\\sin(A) = \\frac{9}{41}$. If the perimeter of triangle $ABC$ is $180$, what is the length of side $BC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'Since $\\sin(A) = \\frac{9}{41}$, the sides opposite and hypotenuse are in the ratio $9:41$. Using the Pythagorean theorem, the adjacent side is in the ratio $\\sqrt{41^2 - 9^2} = \\sqrt{1681 - 81} = \\sqrt{1600} = 40$. So the three sides are in the ratio $9:40:41$. The sum of the ratios is $9 + 40 + 41 = 90$. With a perimeter of $180$, the scale factor is $\\frac{180}{90} = 2$. Side $BC$ is opposite angle $A$, so $BC = 9 \\times 2 = 18$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XEPHBL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A linear model predicts that a plant''s height in centimeters is given by $h = 1.7d + 4.3$, where $d$ is the number of days since planting. According to this model, what does the value 1.7 represent?', NULL, $lyceon_json$[{"key":"A","text":"The height of the plant at the time of planting"},{"key":"B","text":"The predicted increase in height, in centimeters, for each additional day"},{"key":"C","text":"The total height of the plant after 1.7 days"},{"key":"D","text":"The number of days needed for the plant to reach 4.3 centimeters"}]$lyceon_json$::jsonb, 'B', NULL, E'In the equation $h = 1.7d + 4.3$, the coefficient 1.7 is the slope, which represents the predicted change in height for each one-unit increase in $d$. That is, the plant is predicted to grow 1.7 centimeters per day. The height at planting ($d = 0$) is the $y$-intercept, 4.3 centimeters, not 1.7. The total height after 1.7 days would be $1.7(1.7) + 4.3 = 7.19$, which is a specific predicted value, not what the coefficient represents. The number of days to reach 4.3 centimeters is 0, since 4.3 is the initial height when $d = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZQI8L1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $MNP$, angle $M$ is equal to angle $N$. The exterior angle at vertex $P$ measures $146^\\circ$. What is the measure, in degrees, of angle $M$?', NULL, $lyceon_json$[{"key":"A","text":"$34^\\circ$"},{"key":"B","text":"$56^\\circ$"},{"key":"C","text":"$73^\\circ$"},{"key":"D","text":"$107^\\circ$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, the exterior angle at $P$ equals the sum of the two non-adjacent interior angles: $\\angle M + \\angle N = 146^\\circ$. Since $\\angle M = \\angle N$, each equals $\\frac{146}{2} = 73^\\circ$. The value $34^\\circ$ results from computing the interior angle at $P$ ($180 - 146 = 34$) instead of the requested angle $M$. The value $56^\\circ$ arises from an arithmetic error in halving $146$. The value $107^\\circ$ comes from subtracting $73$ from $180$, confusing the supplement with the angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20FTR33', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Marine biologist Tomoko Hayashi observed that giant Pacific octopuses in Puget Sound were avoiding their usual rocky dens and congregating near warm-water outflows from a nearby desalination plant. The behavior puzzled Hayashi, because the species generally prefers cold, oxygen-rich water. After two years of fieldwork, she discovered that the warm outflows attracted dense swarms of shrimp, the octopuses'' preferred prey, creating a foraging opportunity that outweighed the thermal discomfort. Hayashi''s finding suggested that food availability, not temperature preference, was the dominant factor driving the octopuses'' habitat selection in disturbed environments.', $lyceon_json$[{"key":"A","text":"It compares two competing theories of octopus behavior and concludes that both are equally supported by the available evidence from multiple independent research teams."},{"key":"B","text":"It describes the complete life cycle of the giant Pacific octopus from juvenile development through adult reproduction in warm-water coastal habitats across the Pacific region."},{"key":"C","text":"It presents an unexpected observation, identifies why it was surprising, reveals the explanation uncovered through research, and states the broader implication."},{"key":"D","text":"It criticizes prior research on octopus habitat selection for failing to consider the effects of industrial pollution and thermal discharge on marine ecosystems."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage follows a clear four-part progression: it presents the unexpected observation of octopuses near warm outflows, explains why this was puzzling given the species'' cold-water preference, reveals Hayashi''s discovery that prey density explained the behavior, and concludes with the broader implication about food availability versus temperature preference. The choice describing two competing theories is incorrect because the passage presents one puzzle and one explanation, not rival theories treated as equally valid. The choice about the octopus life cycle is wrong because the passage does not discuss juvenile development or reproduction. The choice about criticizing prior research is wrong because the passage describes Hayashi''s own fieldwork and findings without attacking other researchers'' methods or conclusions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
