INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20YOUSS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Horyuji temple complex in Nara Prefecture contains some of the oldest surviving wooden structures in the world_______ architectural historians have long debated whether the original builders used a form of earthquake-resistant joinery that predates modern seismic engineering by over a millennium.', $lyceon_json$[{"key":"A","text":"world, architectural"},{"key":"B","text":"world architectural"},{"key":"C","text":"world; architectural"},{"key":"D","text":"world. The structures, they"}]$lyceon_json$::jsonb, 'C', NULL, E'Two independent clauses appear on either side of the blank: "The Horyuji temple complex in Nara Prefecture contains some of the oldest surviving wooden structures in the world" and "architectural historians have long debated whether the original builders used a form of earthquake-resistant joinery." A semicolon correctly joins two closely related independent clauses without a coordinating conjunction. A comma alone between the two independent clauses creates a comma splice, which is a grammatical error in Standard English. Omitting punctuation entirely produces a run-on sentence, fusing two independent clauses with no separation. The option using a period followed by "The structures, they" introduces a double subject: both "The structures" and "they" serve as the subject of the same clause, producing a nonstandard construction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2210J9F', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Marine biologist Fatimah al-Rashid discovered that certain species of parrotfish in the Red Sea grind coral fragments into fine sand through their specialized pharyngeal teeth. Her surveys along a 14-kilometer reef tract estimated that a single adult parrotfish produces roughly 380 kilograms of sand per year. __________ al-Rashid cautions that overfishing of parrotfish has measurably slowed sediment production on degraded reef sections, threatening the natural replenishment of nearby beaches.', E'Marine biologist Fatimah al-Rashid discovered that certain species of parrotfish in the Red Sea grind coral fragments into fine sand through their specialized pharyngeal teeth. Her surveys along a 14-kilometer reef tract estimated that a single adult parrotfish produces roughly 380 kilograms of sand per year. __________ al-Rashid cautions that overfishing of parrotfish has measurably slowed sediment production on degraded reef sections, threatening the natural replenishment of nearby beaches.', $lyceon_json$[{"key":"A","text":"However,"},{"key":"B","text":"Likewise,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Furthermore,"}]$lyceon_json$::jsonb, 'A', NULL, E'The first two sentences describe the beneficial role parrotfish play in producing sand from coral. The third sentence shifts to a concern: overfishing is reducing that sand production and endangering beaches. "However," correctly signals this shift from a positive finding to a cautionary problem. "Likewise," implies the third sentence mirrors the preceding information, but it introduces a contrasting concern rather than a parallel observation. "For instance," implies the third sentence illustrates one of the preceding claims, but it introduces a new warning about overfishing rather than exemplifying sand production. "Furthermore," implies the third sentence adds a supporting detail in the same direction, but the shift to overfishing as a threat marks a change in direction from the earlier positive description.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22RE65A', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' claim?', E'Marine ecologists studying the Chesapeake Bay have claimed that the recent reintroduction of native oyster beds has improved water clarity in adjacent channels. The researchers attribute this improvement to the filter-feeding behavior of oysters, which remove suspended particles from the water column as they feed on phytoplankton and organic debris.', $lyceon_json$[{"key":"A","text":"The Chesapeake Bay Foundation has allocated \\$2.3 million in new funding for oyster reef restoration projects along the eastern shore over the next three years."},{"key":"B","text":"Native oyster populations in the Chesapeake Bay declined by over 90 percent during the twentieth century due to overharvesting, disease, and habitat degradation."},{"key":"C","text":"Several species of fish that prefer clear-water habitats have been observed near restored oyster beds in the Chesapeake Bay for the first time in over a decade, though researchers have not yet established whether the increased fish activity is caused by improved water clarity or by other environmental factors such as changes in food availability."},{"key":"D","text":"Channels adjacent to restored oyster beds show 41 percent lower concentrations of suspended particulate matter compared to channels of similar depth and flow rate that lack oyster beds."}]$lyceon_json$::jsonb, 'D', NULL, E'The claim is that reintroduced oyster beds have improved water clarity through filter-feeding that removes suspended particles. A finding that channels near restored beds show 41 percent lower suspended particulate matter than comparable channels without beds directly supports this causal mechanism. The finding about new funding for restoration projects describes future plans, not evidence bearing on the claimed water-clarity effect. The finding about historical oyster population decline provides background context but does not address whether reintroduction has improved water clarity. The finding about clear-water fish species returning is consistent with improved clarity but only indirectly supports it, since the fish could have returned for other reasons.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW253U069', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Entomologist Priya Dasgupta and her colleagues at the Indian Institute of Science recently completed a census of dung beetle species in the montane grasslands of the Western Ghats. The team catalogued 53 distinct species across eleven survey sites, seven of which had never been documented in any prior inventory of the region. Dasgupta notes that dung beetles play a critical role in nutrient cycling by breaking down animal waste and returning nitrogen and phosphorus to the soil, making their diversity an important indicator of grassland ecosystem health.', $lyceon_json$[{"key":"A","text":"Dung beetles are the primary source of nitrogen and phosphorus in montane grassland soils throughout southern India, a finding confirmed by Dasgupta's extensive census of the Western Ghats region."},{"key":"B","text":"The Indian Institute of Science has undertaken an ambitious multi-decade program to document every insect species in the Western Ghats."},{"key":"C","text":"A recent census in the Western Ghats identified a greater diversity of dung beetle species than previously known, underscoring the insects' ecological significance."},{"key":"D","text":"Priya Dasgupta believes that dung beetle populations in the Western Ghats are declining due to habitat loss and overgrazing by livestock."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes a census that found 53 dung beetle species, including seven previously undocumented ones, and emphasizes their role in nutrient cycling and ecosystem health. The option about the census identifying greater diversity than previously known and underscoring ecological significance captures this central point. The option about dung beetles being the primary source of nitrogen and phosphorus overstates their role; the passage says they contribute to nutrient cycling, not that they are the primary source. The option about a multi-decade program to document every insect species introduces information not present in the passage. The option about declining populations due to habitat loss and overgrazing attributes claims to Dasgupta that the passage never makes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW261C7BV', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Urban planner Koji Watanabe studied pedestrian traffic patterns in the Shimokitazawa neighborhood of Tokyo before and after the removal of a major elevated railway in 2019. Watanabe found that foot traffic on streets formerly shaded by the railway structure increased by 29 percent on weekdays and 44 percent on weekends after its removal, even though no new commercial establishments had opened on those streets during the study period. Watanabe concluded that the increase was most likely attributable to ________', $lyceon_json$[{"key":"A","text":"a citywide population increase that brought more residents to all neighborhoods in western Tokyo during the same period, combined with new public transit connections that made Shimokitazawa more accessible from surrounding districts."},{"key":"B","text":"improved environmental conditions on those streets, such as greater sunlight and reduced noise, that made them more attractive to pedestrians."},{"key":"C","text":"a marketing campaign by local business owners designed to draw visitors to the Shimokitazawa neighborhood."},{"key":"D","text":"the construction of new residential buildings on the site where the elevated railway had previously stood."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that foot traffic increased on streets formerly shaded by the elevated railway after its removal, even without new commercial openings. The most logical inference is that the railway''s removal improved the physical environment of those streets — more sunlight, less noise and visual obstruction — making them more appealing to walk along. The option about citywide population increase and new transit connections does not explain why the increase was concentrated specifically on streets formerly under the railway. The option about a marketing campaign introduces an external factor the passage does not mention and would not specifically account for the pattern on formerly shaded streets. The option about new residential construction on the railway site is not supported by the passage and would not specifically explain increased foot traffic on streets that were shaded by the structure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW293Y6W2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Ethnomusicologist Luisa Ferreira has argued that the berimbau, the single-string percussion instrument central to capoeira, was brought to Brazil by enslaved West Africans and retained its original tuning system for over three centuries. Recent spectral analyses of museum-archived berimbaus from the 1870s, however, reveal pitch frequencies consistent with Portuguese folk scales rather than West African tonal patterns. __________ Ferreira has revised her position, proposing that while the instrument''s physical form remained African, its tuning was gradually adapted under the influence of the colonial musical environment.', E'Ethnomusicologist Luisa Ferreira has argued that the berimbau, the single-string percussion instrument central to capoeira, was brought to Brazil by enslaved West Africans and retained its original tuning system for over three centuries. Recent spectral analyses of museum-archived berimbaus from the 1870s, however, reveal pitch frequencies consistent with Portuguese folk scales rather than West African tonal patterns. __________ Ferreira has revised her position, proposing that while the instrument''s physical form remained African, its tuning was gradually adapted under the influence of the colonial musical environment.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"In light of this evidence,"},{"key":"C","text":"Regardless,"},{"key":"D","text":"To illustrate,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes Ferreira''s original claim about African tuning, then introduces spectral evidence contradicting it. The third sentence describes Ferreira revising her position in response to the new data. "In light of this evidence," correctly signals that Ferreira''s revision was prompted by the spectral findings described in the preceding sentence. "Similarly," implies the third sentence presents a parallel situation, but it describes a revision caused by the contradictory evidence, not a comparable finding. "Regardless," implies Ferreira maintained her position despite the evidence, but she actually revised it because of the evidence. "To illustrate," implies the third sentence provides an example of the spectral findings, but it instead describes Ferreira''s changed conclusion in response to those findings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BAJJBV', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what is the meaning of "tempered"?', E'The glassblower Adaeze Nwosu was known for designs that balanced flamboyance with restraint. Even her most elaborate vases displayed a tempered use of color: vivid cobalt bands were interspersed with wide stretches of clear glass, preventing the pieces from becoming visually overwhelming.', $lyceon_json$[{"key":"A","text":"heated to an extreme degree"},{"key":"B","text":"unplanned, haphazard, and chaotic"},{"key":"C","text":"restrained"},{"key":"D","text":"permanently and irreversibly destroyed"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage states that vivid cobalt bands were interspersed with wide stretches of clear glass to prevent the pieces from becoming visually overwhelming, indicating that the use of color was controlled and held back. "Restrained" captures this sense of moderation and deliberate limitation. "Heated to an extreme degree" refers to the metallurgical or glassmaking process of tempering through heat, which does not fit the context of describing how color is applied in a design. "Unplanned, haphazard, and chaotic" contradicts the passage''s emphasis on balance and deliberate spacing of color. "Permanently and irreversibly destroyed" introduces a meaning of destruction that has no connection to the passage''s description of a careful aesthetic choice.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BBYYHL', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Musicologist Helena Varga has studied the critical reception of Hungarian composer Gyorgy Ligeti''s orchestral work Atmospheres (1961) in the years immediately following its premiere. Varga notes that early reviews in German-language music journals praised the piece primarily for its timbral innovations — its use of dense, slowly shifting tone clusters that obscured individual pitches. However, Varga points out that Ligeti himself repeatedly emphasized in interviews from the same period that Atmospheres was fundamentally a work about the perception of musical time, not about timbre. Varga argues that this discrepancy between critical reception and authorial intent suggests that ________', $lyceon_json$[{"key":"A","text":"the German-language critics who reviewed Atmospheres were unfamiliar with Ligeti's earlier compositions and therefore lacked the context needed to understand his intentions."},{"key":"B","text":"Ligeti changed his artistic priorities between the composition and the premiere of Atmospheres, initially conceiving the piece as a study of timbre and only later reframing it as an exploration of temporal perception during interviews."},{"key":"C","text":"Ligeti's timbral innovations were so perceptually striking that they overshadowed the temporal dimension of the work, leading critics to emphasize the more immediately audible feature."},{"key":"D","text":"German-language music criticism in the early 1960s was methodologically incapable of analyzing temporal structures in orchestral music because its analytical vocabulary was derived exclusively from tonal harmonic theory, leaving critics without the conceptual tools needed to describe the kind of temporal distortion Ligeti was pursuing."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage presents a gap between critics who focused on Atmospheres'' timbral features and Ligeti''s own emphasis on temporal perception. The most logical completion is that the timbral innovations were so striking that they dominated critics'' attention, causing them to overlook the temporal dimension Ligeti considered central. The option about critics being unfamiliar with Ligeti''s earlier work introduces a biographical claim the passage does not support. The option about Ligeti changing his priorities implies inconsistency that the passage does not suggest; Varga treats the discrepancy as a gap in reception, not a shift in the composer''s views. The option about German criticism being methodologically incapable of temporal analysis makes an extreme claim about an entire critical tradition that goes far beyond what the passage warrants.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CVG2AN', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Olena Kovalchuk has challenged the widely held view that the city of Lviv experienced uninterrupted economic decline throughout the seventeenth century. Drawing on newly digitized customs records from the Lviv municipal archive, Kovalchuk demonstrates that the city''s overland trade with Ottoman merchants actually expanded between 1640 and 1672, a period during which conventional accounts emphasize only the devastation caused by successive military conflicts. Kovalchuk acknowledges that the wars did severely disrupt certain industries, particularly tanning and textile production, but argues that the simultaneous growth in transit trade revenues created pockets of prosperity that existing historiography has overlooked.', $lyceon_json$[{"key":"A","text":"Kovalchuk uses customs records to argue that Lviv's seventeenth-century economy was more complex than standard accounts suggest, with trade growth coexisting alongside wartime industrial decline."},{"key":"B","text":"Newly digitized archives have revealed that Lviv's tanning and textile industries were far more profitable during the seventeenth century than historians previously believed, even during periods of military conflict."},{"key":"C","text":"Kovalchuk contends that Ottoman merchants were primarily responsible for the economic recovery of Lviv following the destructive wars of the mid-seventeenth century and the collapse of overland trade routes."},{"key":"D","text":"The digitization of the Lviv municipal archive has enabled historians to reconstruct the daily lives of ordinary merchants and artisans in seventeenth-century eastern Europe with unprecedented detail and specificity."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Kovalchuk''s argument that Lviv''s economy was not in uniform decline during the seventeenth century: while wars did harm certain industries, overland trade with Ottoman merchants grew, creating overlooked prosperity. The option describing a more complex economy with trade growth alongside industrial decline captures this nuanced argument. The option about tanning and textile industries being more profitable contradicts the passage, which states those industries were severely disrupted. The option about Ottoman merchants being primarily responsible for economic recovery mischaracterizes the argument; Kovalchuk describes pockets of prosperity, not a full recovery driven by Ottoman trade. The option about reconstructing daily lives of merchants and artisans introduces a focus the passage does not discuss.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FHIEMN', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ICYA8L', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Traditional Okinawan pottery, known as yachimun, has been produced on the island for over six hundred years using local red clay and wood-fired kilns called noborigama. [underline]Today, fewer than forty potters continue this practice full-time.[/underline] The Okinawan prefectural government has responded by designating several master potters as living cultural treasures and funding apprenticeship programs intended to train a new generation of artisans.', $lyceon_json$[{"key":"A","text":"It provides a detailed technical explanation of the noborigama kiln-firing process and the chemical composition of the red clay."},{"key":"B","text":"It establishes the declining state of the tradition that the government response described afterward aims to address."},{"key":"C","text":"It argues that yachimun pottery is aesthetically superior to other Japanese ceramic traditions and deserves wider recognition."},{"key":"D","text":"It lists the specific government agencies and administrative bodies responsible for cultural preservation in Okinawa."}]$lyceon_json$::jsonb, 'B', NULL, E'The underlined sentence states that fewer than forty potters continue the practice full-time, establishing a sense of decline that motivates the government actions described in the next sentence. It connects the historical background of the tradition to the preservation efforts that follow. The choice about providing a technical explanation of the kiln-firing process and clay composition is incorrect because the underlined sentence addresses the number of remaining practitioners, not how the kilns operate. The choice about arguing for aesthetic superiority over other Japanese ceramics is wrong because the sentence makes no evaluative comparison with other traditions. The choice about listing specific government agencies is wrong because the sentence mentions no agencies; the government designations and programs appear in the following sentence, not the underlined one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ILPZ8T', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'The Haenyeo, female free-divers of Jeju Island in South Korea, traditionally harvested abalone and sea urchins without supplemental oxygen at depths of up to twenty meters. __________ in 2016, UNESCO inscribed the Haenyeo diving culture on its Representative List of the Intangible Cultural Heritage of Humanity.', E'The Haenyeo, female free-divers of Jeju Island in South Korea, traditionally harvested abalone and sea urchins without supplemental oxygen at depths of up to twenty meters. __________ in 2016, UNESCO inscribed the Haenyeo diving culture on its Representative List of the Intangible Cultural Heritage of Humanity.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Recognizing this tradition,"},{"key":"C","text":"In other words,"},{"key":"D","text":"On the contrary,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence describes the Haenyeo''s longstanding diving practice, and the second sentence describes UNESCO''s decision to honor that practice. "Recognizing this tradition," correctly signals that UNESCO''s inscription was a response to the cultural significance described in the first sentence. "Nevertheless," implies the UNESCO inscription occurred despite some obstacle in the first sentence, but no obstacle is presented. "In other words," implies the second sentence restates the first, but the UNESCO inscription is new information, not a restatement. "On the contrary," implies the second sentence contradicts the first, but there is no opposition between the two ideas.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J12SP1', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a research study, if accurate, would most effectively illustrate the phenomenon described in the text?', E'Sociolinguist Amira Bouzid has documented a pattern she calls "prestige reversal" in multilingual communities in northern Morocco. In these communities, the local Amazigh (Berber) language was historically stigmatized in formal and educational contexts, where French and Modern Standard Arabic held prestige. Bouzid has found, however, that younger speakers increasingly associate Amazigh with cultural authenticity and social solidarity, using it deliberately in contexts — such as university student organizations and social media — where French or Arabic had previously been the default. Crucially, Bouzid observes that this shift does not reflect increased fluency in Amazigh among younger speakers; rather, even those with limited Amazigh proficiency deploy symbolic phrases and code-switches to signal in-group identity.', $lyceon_json$[{"key":"A","text":"\"Participants in the bilingual education cohort demonstrated significantly higher scores on standardized Amazigh reading comprehension assessments after 18 months of instruction, suggesting that formal classroom training can effectively reverse heritage language attrition among young adults.\""},{"key":"B","text":"\"Among respondents aged 18 to 24, 73 percent reported inserting Amazigh greetings or proverbs into French-language social media posts specifically to express cultural pride, despite rating their own Amazigh conversational fluency as 'basic' or 'minimal.'\""},{"key":"C","text":"\"The Moroccan Ministry of Education's 2019 curriculum reform mandating Amazigh instruction in primary schools has resulted in measurable increases in student enrollment in Amazigh-language courses across all twelve administrative regions.\""},{"key":"D","text":"\"Interviews with elder Amazigh speakers in rural communities revealed widespread concern that younger generations are abandoning the language entirely in favor of French, which they perceive as essential for professional advancement in urban labor markets.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The phenomenon described is prestige reversal: younger speakers with limited Amazigh proficiency deliberately use symbolic Amazigh phrases in formerly French- or Arabic-dominant contexts to signal cultural identity. The quotation about 18-to-24-year-olds inserting Amazigh greetings into French-language social media despite rating their own fluency as basic or minimal directly illustrates both the symbolic deployment and the limited-proficiency aspect of prestige reversal. The quotation about bilingual education improving reading comprehension scores addresses language acquisition through formal instruction, not the symbolic identity-signaling phenomenon Bouzid describes. The quotation about government curriculum reform and enrollment increases describes institutional policy effects, not the grassroots prestige reversal among younger speakers. The quotation about elder speakers expressing concern over language abandonment describes the opposite of prestige reversal, portraying Amazigh as losing ground rather than gaining symbolic prestige.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JBCOE6', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Behavioral economist Suki Nakamura has investigated how people evaluate charitable organizations when presented with two types of performance data: outcome metrics (such as the number of individuals served or the measurable improvement in recipients'' well-being) and efficiency metrics (such as the percentage of donations spent directly on programs rather than on administrative costs). In a series of experiments, Nakamura found that donors who received only efficiency data rated an organization as more trustworthy than donors who received only outcome data, even when the outcome data indicated significantly greater social impact. However, donors who received both types of data simultaneously rated organizations primarily on the basis of outcomes, largely disregarding efficiency figures. Nakamura concludes that efficiency metrics dominate donor judgment when they are the sole available indicator, but ________', $lyceon_json$[{"key":"A","text":"this dominance disappears when outcome data are also available, suggesting that donors treat efficiency as a proxy for impact rather than valuing it independently."},{"key":"B","text":"this pattern reflects donors' inherent distrust of outcome metrics, which they regard as easily manipulated by organizations seeking to inflate their apparent social impact."},{"key":"C","text":"charitable organizations should therefore prioritize reporting efficiency metrics over outcome metrics in their public communications to maximize donor trust and long-term fundraising revenue."},{"key":"D","text":"donors who receive both types of data experience cognitive overload that prevents them from processing efficiency figures, causing them to default to whichever metric appears first in the presentation order."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that efficiency metrics dominated when presented alone, but when outcome data were also available, donors shifted to evaluating organizations primarily by outcomes. The most logical completion of Nakamura''s conclusion is that efficiency''s dominance vanishes in the presence of outcome data, implying donors use efficiency as a stand-in for impact information rather than caring about efficiency for its own sake. The option about donors distrusting outcome metrics as manipulable contradicts the finding that donors preferred outcomes when both data types were available. The option recommending organizations prioritize efficiency reporting is a prescriptive claim the passage does not support, especially since the findings show outcomes dominate when both are present. The option about cognitive overload causing default to whichever metric appears first introduces a mechanism the passage does not describe or test.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NLJ4F6', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare jade figurines displayed in the Taipei National Palace Museum_______ visitors from around the world who are drawn to the intricate craftsmanship of Qing dynasty artisans.', $lyceon_json$[{"key":"A","text":"attract"},{"key":"B","text":"attracts"},{"key":"C","text":"have attracted"},{"key":"D","text":"are attracting"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," a singular noun. The intervening prepositional phrase "of rare jade figurines" and the participial phrase "displayed in the Taipei National Palace Museum" do not change the number of the subject. A singular subject requires a singular verb form. The option "attracts" correctly provides a third-person singular present-tense verb consistent with a general statement of fact. The bare plural form "attract" does not agree with the singular subject "collection." The present-perfect plural "have attracted" incorrectly treats "figurines" as the subject and shifts the tense. The present-progressive plural "are attracting" also fails to agree with the singular "collection" and implies a temporary ongoing action rather than a habitual one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OJCA39', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what is the meaning of "protracted"?', E'Negotiations between the dockworkers'' union and the shipping consortium had been protracted, stretching across eleven months without yielding a single provisional agreement. Each side accused the other of introducing last-minute conditions that reset discussions to their starting point, and by the ninth round of talks the mediator had begun drafting contingency plans for an indefinite work stoppage.', $lyceon_json$[{"key":"A","text":"kept entirely secret from public scrutiny and media attention"},{"key":"B","text":"drawn out over an extended period"},{"key":"C","text":"resolved rapidly and with minimal disagreement"},{"key":"D","text":"abandoned before any meaningful progress was made"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes negotiations stretching across eleven months without yielding a provisional agreement, with nine rounds of talks and a mediator drafting contingency plans. This context establishes that the negotiations lasted far longer than expected, and "drawn out over an extended period" captures this meaning of prolonged duration. "Kept entirely secret from public scrutiny and media attention" introduces a concept of confidentiality that is never mentioned in the passage. "Resolved rapidly and with minimal disagreement" directly contradicts the passage''s description of eleven months without agreement. "Abandoned before any meaningful progress was made" is incorrect because the passage indicates that talks continued through multiple rounds, not that they were given up entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OTXWGZ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what is the meaning of "plastic"?', E'Neuroscientist Hana Kowalczyk''s longitudinal study of bilingual children in Gdansk revealed that the young brain is remarkably plastic. Children who acquired a second language before age seven showed cortical reorganization in regions associated with executive function, developing neural pathways that monolingual peers did not exhibit until years later, if at all. Kowalczyk concluded that early linguistic immersion physically reshapes the brain''s architecture.', $lyceon_json$[{"key":"A","text":"composed of synthetic manufactured material"},{"key":"B","text":"superficial, unconvincing, and lacking substance"},{"key":"C","text":"rigidly resistant to any form of alteration"},{"key":"D","text":"capable of being reshaped"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage describes cortical reorganization, the development of new neural pathways, and the physical reshaping of the brain''s architecture through early linguistic immersion. This context makes clear that "plastic" refers to the brain''s capacity to be molded and restructured, which is captured by "capable of being reshaped." "Composed of synthetic manufactured material" invokes the common everyday meaning of plastic as a manufactured substance, which is irrelevant to a discussion of neuroscience. "Superficial, unconvincing, and lacking substance" introduces a pejorative meaning that contradicts the passage''s characterization of the brain''s adaptability as remarkable and significant. "Rigidly resistant to any form of alteration" is the opposite of the meaning established by the passage, which emphasizes the brain''s malleability and capacity for change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OYEE3U', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the hypothesis described in the text?', E'Geochemist Lars Henriksen has hypothesized that the unusually high concentration of iridium found in 74-million-year-old sedimentary layers at a site in central Montana originated from prolonged volcanic activity in the Deccan Traps region of what is now India, rather than from an extraterrestrial impact event. Henriksen points to isotopic ratios in the iridium-bearing layer that, he argues, are more consistent with volcanic than with meteoric sources.', $lyceon_json$[{"key":"A","text":"Subsequent analysis of the Montana sedimentary layers reveals osmium isotope ratios that closely match those found in known meteorite fragments and diverge sharply from ratios characteristic of Deccan Traps volcanic emissions."},{"key":"B","text":"The Deccan Traps eruptions are estimated to have released approximately three times more sulfur dioxide into the atmosphere than any other volcanic event in the past 100 million years."},{"key":"C","text":"Iridium concentrations in the Montana site are roughly 17 times higher than those found in typical crustal rocks but lower than those measured at confirmed impact sites elsewhere in North America."},{"key":"D","text":"Paleontological surveys of the Montana site have uncovered fossils of marine organisms that are known to have gone extinct shortly before the end-Cretaceous mass extinction event approximately 66 million years ago, raising questions about whether the iridium anomaly at this older site could be linked to a separate geological event that preceded the more widely studied boundary."}]$lyceon_json$::jsonb, 'A', NULL, E'Henriksen''s hypothesis rests on isotopic ratios he claims are more consistent with volcanic than meteoric sources. A finding that osmium isotope ratios in the same layers match meteorite signatures and diverge from Deccan Traps signatures would directly undermine his isotopic evidence and thus weaken the hypothesis. The finding about sulfur dioxide output from the Deccan Traps describes volcanic intensity but does not address whether the iridium at the Montana site came from that source. The finding about iridium concentrations being lower than at confirmed impact sites is ambiguous rather than directly weakening, since the hypothesis concerns origin, not concentration level. The finding about marine fossils and their extinction timing introduces paleontological context unrelated to the geochemical question of iridium origin.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
