INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QWR4RW', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the Chilean observatory''s adaptive optics system completed its final calibration in March 2024, astronomer Dr. Lucia Herrera_______ the same binary star system for eleven consecutive years, amassing a dataset that would later reshape models of stellar evolution in low-metallicity environments.', $lyceon_json$[{"key":"A","text":"studied"},{"key":"B","text":"has been studying"},{"key":"C","text":"had been studying"},{"key":"D","text":"would study"}]$lyceon_json$::jsonb, 'C', NULL, E'The construction "By the time [past-tense event]" signals that another action was ongoing up to and before that past event, requiring the past perfect progressive tense. The duration marker "for eleven consecutive years" further confirms that the action was continuous over an extended period leading up to the calibration. The option "had been studying" correctly places the ongoing study before the past reference point of the calibration''s completion. The simple past "studied" fails to establish the required temporal sequence showing an action in progress before another past event and does not pair correctly with the "by the time" construction. The present-perfect progressive "has been studying" anchors the action to the present moment, which conflicts with the entirely past-tense narrative. The conditional "would study" implies a hypothetical or planned future action, contradicting the passage''s indication that the observation was a completed, ongoing endeavor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TJ83G3', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead archaeologist nor her three graduate assistants_______ able to explain why the burial site contained fragments of obsidian that could only have originated from a volcanic deposit more than two thousand kilometers away.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"is"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb agrees in number with the subject closer to it. Here, "her three graduate assistants" is the nearer subject and is plural, so the verb must also be plural. The option "were" correctly provides a plural past-tense verb agreeing with "assistants." The singular past-tense "was" incorrectly treats "the lead archaeologist" as the governing subject for agreement. The singular present-perfect "has been" fails on both number (singular rather than plural) and tense (present perfect rather than simple past, inconsistent with the past-tense "contained" in the clause that follows). The singular present-tense "is" fails on both number and tense for the same reasons.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
