INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VUKEAX', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Cognitive scientist Renata Oliveira has proposed a reinterpretation of the well-documented "generation effect" in memory research — the finding that people remember information better when they actively produce it rather than passively read it. Most accounts attribute this advantage to deeper semantic processing during generation. Oliveira argues, however, that the effect is substantially mediated by prediction error: when a person generates a response and the produced item deviates from their initial expectation, the resulting surprise signal strengthens encoding. In a series of experiments using cued word-pair tasks, Oliveira found that generation improved recall only when participants reported that their generated responses surprised them; when participants rated their generated responses as expected, their recall was statistically indistinguishable from that of participants who merely read the same word pairs. Oliveira concedes that semantic processing likely contributes to the effect but maintains it is insufficient as a standalone explanation.', $lyceon_json$[{"key":"A","text":"Oliveira's research demonstrates that the generation effect is entirely an artifact of experimental design and does not reflect a genuine memory advantage in naturalistic learning contexts."},{"key":"B","text":"Oliveira proposes that prediction error, rather than semantic processing alone, substantially explains why generating information enhances memory, citing evidence that generation aids recall only when the produced response is surprising."},{"key":"C","text":"Oliveira's experiments reveal that people who passively read word pairs consistently outperform those who generate responses, contradicting decades of research on the generation effect."},{"key":"D","text":"Oliveira argues that the generation effect occurs because producing information forces learners to engage in deeper semantic processing than they would during passive reading, a mechanism she validates through cued word-pair experiments that systematically measure participants' self-reported cognitive effort across multiple encoding conditions."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Oliveira''s reinterpretation of the generation effect: she argues that prediction error, not just semantic processing, substantially mediates the memory advantage of generating information, and her experiments show generation improved recall only when responses were surprising. The option identifying prediction error as the substantial explanatory factor, supported by the surprise-contingent recall finding, accurately captures this central argument. The option calling the generation effect an artifact of experimental design misrepresents Oliveira, who accepts the effect is real but offers a different mechanism. The option claiming passive readers outperformed generators directly contradicts the passage''s findings. The option attributing the advantage solely to deeper semantic processing describes the conventional account that Oliveira challenges, not her own position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VZ94VI', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the primary purpose of the text?', E'Historian Fatou Diallo''s 2021 study reexamines the collapse of the Jolof Empire in West Africa during the sixteenth century. The conventional account attributes the empire''s disintegration to Portuguese military intervention along the Senegalese coast. Diallo does not dispute that Portuguese raids destabilized coastal vassal states, but she argues that the decisive factor was an internal fiscal crisis triggered by the diversion of trans-Saharan gold routes eastward to Bornu. Deprived of the revenue that had sustained its centralized administration, the Jolof court could no longer subsidize the provincial garrisons that enforced its authority over subordinate kingdoms. Diallo contends that the empire would have fragmented even without European contact, though the timing and pattern of secession might have differed.', $lyceon_json$[{"key":"A","text":"It presents a historian's argument that an empire's collapse was driven primarily by internal economic causes rather than by the external military factor emphasized in the standard narrative."},{"key":"B","text":"It offers a comprehensive military history of Portuguese colonial campaigns along the entire West African coast during the sixteenth century and evaluates their strategic effectiveness."},{"key":"C","text":"It argues that the Jolof Empire never actually collapsed and that historians across multiple disciplines have fundamentally misunderstood its political structure."},{"key":"D","text":"It evaluates the relative economic productivity of trans-Saharan and coastal Atlantic trade networks without taking a position on the causes of political change in the region."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces the conventional external explanation for the Jolof Empire''s collapse, then presents Diallo''s alternative argument that an internal fiscal crisis caused by the diversion of gold routes was the decisive factor, concluding with her claim that fragmentation would have occurred even without European contact. This purpose is accurately described as presenting a historian''s argument that internal economic causes, rather than external military intervention, drove the collapse. The choice about a comprehensive military history of Portuguese campaigns is wrong because the passage focuses on the Jolof Empire''s internal dynamics, not on Portuguese military operations. The choice about the empire never having collapsed is wrong because Diallo accepts the collapse as historical fact and merely reattributes its primary cause. The choice about evaluating trade networks without taking a position is wrong because Diallo explicitly takes a position, arguing that the fiscal crisis was the decisive factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XE1OEB', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best states a relationship between the two texts?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y3M78V', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The restoration of the Uffizi Gallery''s fifteenth-century altarpiece took an unexpected turn when conservators discovered, beneath layers of later overpainting_______ a portrait that bore no resemblance to the figure depicted in the visible composition and that appeared to predate the altarpiece itself by at least forty years.', $lyceon_json$[{"key":"A","text":"overpainting, a"},{"key":"B","text":"overpainting; a"},{"key":"C","text":"overpainting a"},{"key":"D","text":"overpainting. A"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "beneath layers of later overpainting" is a parenthetical modifier inserted between the verb "discovered" and its direct object "a portrait." Because this parenthetical was opened with a comma before "beneath," it must be closed with a matching comma after "overpainting" to complete the pair. The option placing a comma after "overpainting" correctly closes the parenthetical and allows the sentence to continue to the direct object. A semicolon is incorrect because there are not two independent clauses on either side of the blank; "a portrait that bore no resemblance..." is a noun phrase serving as the direct object, not an independent clause. Omitting punctuation leaves the opening comma before "beneath" unpaired and produces a construction that obscures the relationship between "discovered" and its object "a portrait." A period after "overpainting" would leave "A portrait that bore no resemblance to the figure depicted in the visible composition and that appeared to predate the altarpiece itself by at least forty years" as a sentence fragment, since it consists of a noun phrase with relative clauses but no main verb.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZWZX7P', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After spending nearly fourteen months analyzing sediment cores extracted from Lake Malawi_______ geochemist Dr. Farai Moyo published a study revealing that the lake''s phosphorus concentrations had fluctuated dramatically over the past eight centuries.', $lyceon_json$[{"key":"A","text":"Malawi, geochemist"},{"key":"B","text":"Malawi. Geochemist"},{"key":"C","text":"Malawi; geochemist"},{"key":"D","text":"Malawi geochemist"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with a dependent adverbial phrase introduced by "After," which must be followed by a comma before the main clause. The option placing a comma after "Malawi" correctly sets off the introductory dependent phrase from the independent clause that follows. A period after "Malawi" is incorrect because it would leave "After spending nearly fourteen months analyzing sediment cores extracted from Lake Malawi" as a sentence fragment, since it lacks a main verb and cannot stand alone. A semicolon is incorrect because it requires independent clauses on both sides, but the opening phrase beginning with "After" is dependent, not independent. Omitting punctuation entirely produces a run-together construction that violates standard conventions for setting off introductory elements.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}